-- CA Helper demo data: the demo accounts (@demo.local), their CAs and 14 demo businesses.
--
-- Run it on a database that has the tables (flask db upgrade) and the rules (flask seed):
--   docker compose exec -T db psql -U ca_helper -d ca_helper < backend/demo_data.sql
-- or on Neon:
--   psql "<the Neon URL without +psycopg>" -f backend/demo_data.sql
--
-- Safe to run again: it first removes the old demo data. Rows of other accounts are kept;
-- demo users and CA profiles are updated in place, so links to them keep working.
-- The PAN, GSTIN, TAN and phone values are encrypted with the team's FIELD_ENCRYPTION_KEY.
-- Deadlines are fixed dates from the day this file was made.

BEGIN;

-- 1. Remove the old demo data ---------------------------------------------------------------
CREATE TEMP TABLE demo_users ON COMMIT DROP AS
  SELECT id FROM users WHERE email LIKE '%@demo.local';
CREATE TEMP TABLE demo_businesses ON COMMIT DROP AS
  SELECT id FROM businesses WHERE user_id IN (SELECT id FROM demo_users);
CREATE TEMP TABLE demo_items ON COMMIT DROP AS
  SELECT id FROM compliance_items WHERE business_id IN (SELECT id FROM demo_businesses);
CREATE TEMP TABLE demo_engagements ON COMMIT DROP AS
  SELECT id FROM engagements WHERE business_id IN (SELECT id FROM demo_businesses);
CREATE TEMP TABLE demo_documents ON COMMIT DROP AS
  SELECT id FROM documents WHERE owner_id IN (SELECT id FROM demo_users);
CREATE TEMP TABLE demo_cas ON COMMIT DROP AS
  SELECT id FROM ca_profiles WHERE user_id IN (SELECT id FROM demo_users);

DELETE FROM reminder_log WHERE compliance_item_id IN (SELECT id FROM demo_items);
DELETE FROM document_requests WHERE engagement_id IN (SELECT id FROM demo_engagements)
  OR compliance_item_id IN (SELECT id FROM demo_items);
UPDATE document_requests SET document_id = NULL WHERE document_id IN (SELECT id FROM demo_documents);
DELETE FROM ratings WHERE engagement_id IN (SELECT id FROM demo_engagements);
DELETE FROM engagement_items WHERE engagement_id IN (SELECT id FROM demo_engagements)
  OR compliance_item_id IN (SELECT id FROM demo_items);
DELETE FROM engagements WHERE id IN (SELECT id FROM demo_engagements);
DELETE FROM checklist_ticks WHERE compliance_item_id IN (SELECT id FROM demo_items);
DELETE FROM compliance_item_documents WHERE compliance_item_id IN (SELECT id FROM demo_items)
  OR document_id IN (SELECT id FROM demo_documents);
UPDATE compliance_items SET acknowledgement_document_id = NULL
  WHERE acknowledgement_document_id IN (SELECT id FROM demo_documents);
DELETE FROM compliance_items WHERE id IN (SELECT id FROM demo_items);
DELETE FROM regulatory_profiles WHERE business_id IN (SELECT id FROM demo_businesses);
DELETE FROM businesses WHERE id IN (SELECT id FROM demo_businesses);
UPDATE ca_profiles SET cop_document_id = NULL WHERE cop_document_id IN (SELECT id FROM demo_documents);
DELETE FROM documents WHERE id IN (SELECT id FROM demo_documents);
DELETE FROM ca_services WHERE ca_profile_id IN (SELECT id FROM demo_cas);
DELETE FROM notifications WHERE user_id IN (SELECT id FROM demo_users);
DELETE FROM email_otps WHERE user_id IN (SELECT id FROM demo_users);

-- 2. Add the demo data ----------------------------------------------------------------------

